using UnityEngine;
using UnityEditor;
using System.Linq;
using ConRoi.Investigation.V36;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            var c = s.movement.controller;
            var b = c.bounds;
            foreach (var h in Physics.CapsuleCastAll(b.center + Vector3.up * (b.extents.y - c.radius), b.center - Vector3.up * (b.extents.y - c.radius), c.radius, Vector3.right, 1))
                r.Log("block=" + h.collider.name + " p=" + h.point + " bounds=" + h.collider.bounds + " path=" + UnityEditor.AnimationUtility.CalculateTransformPath(h.collider.transform, null));
        }
    }
}

